package com.rpb.reservation.workforce.leave.account;
import static com.rpb.reservation.workforce.leave.account.LeaveAccountDtos.*;
import com.rpb.reservation.workforce.compliance.*;import com.rpb.reservation.workforce.application.*;
import com.rpb.reservation.workforce.persistence.WorkforceEmployeeRepository;import com.rpb.reservation.workforce.domain.WorkforceException;
import com.rpb.reservation.walkin.api.CurrentActor;
import java.math.*;import java.time.*;import java.util.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class LeaveAccountService {
 private final WorkforceAccess gate;private final ComplianceAccess access;private final ComplianceRepository policies;private final WorkforceEmployeeRepository employees;private final LeaveAccountRepository repo;private final LeaveBalanceEngine engine;private final WorkforceAudit audit;private final com.rpb.reservation.workforce.leave.LeaveTypeRepository types;
 public LeaveAccountService(WorkforceAccess gate,ComplianceAccess access,ComplianceRepository policies,WorkforceEmployeeRepository employees,LeaveAccountRepository repo,LeaveBalanceEngine engine,WorkforceAudit audit,com.rpb.reservation.workforce.leave.LeaveTypeRepository types){this.gate=gate;this.access=access;this.policies=policies;this.employees=employees;this.repo=repo;this.engine=engine;this.audit=audit;this.types=types;}
 public Page page(CurrentActor a,UUID store,UUID employee,int year){var e=access.employee(a,store,employee,false);year(year);return new Page(employee,e.name(),year,gate.managedStores(a).containsAll(e.storeIds())&&!a.actorId().equals(e.accountId()),repo.accounts(a.tenantId(),employee,year).stream().filter(x->x.companyId().equals(e.companyId())).map(x->engine.balance(a.tenantId(),x)).toList());}
 private void year(int y){if(y<2000||y>2100)throw WorkforceException.invalid();}
 private void note(String s){if(s==null||s.isBlank()||s.length()>1000)throw WorkforceException.invalid();}
 private boolean start(CurrentActor a,UUID store,UUID command,UUID employee,String kind,Object c){if(command==null||employee==null)throw WorkforceException.invalid();gate.sourceWrite(a);access.employee(a,store,employee,true);employees.lock(employee);policies.lock(a.tenantId(),"command:"+command);return policies.replay(a,store,command,kind,c,Page.class).isPresent();}
 private Page finish(CurrentActor a,UUID store,UUID id,UUID employee,int year,String kind,Object c){var result=page(a,store,employee,year);policies.receipt(a,store,id,kind,c,result);audit.changed(a,store,"leave-account."+kind,id,null,c);return result;}
 @Transactional public Page enable(CurrentActor a,UUID store,UUID id,Enable c){if(c==null||c.employeeId()==null||c.contractId()==null||c.openingOn()==null||c.openingOn().getYear()!=c.year()||c.openings()==null||c.openings().isEmpty()||c.openings().size()>4)throw WorkforceException.invalid();year(c.year());note(c.note());if(start(a,store,id,c.employeeId(),"enable",c))return policies.replay(a,store,id,"enable",c,Page.class).orElseThrow();var e=access.employee(a,store,c.employeeId(),true);access.notSelf(a,e);var contract=policies.contracts(a.tenantId(),e.id()).stream().filter(x->x.id().equals(c.contractId())&&x.companyId().equals(e.companyId())).findFirst().orElseThrow(WorkforceException::missing);if(repo.leftOn(a.tenantId(),e.id()).map(left->c.openingOn().isAfter(left)).orElse(false))throw WorkforceException.invalid();if(c.openingOn().isBefore(contract.effectiveFrom())||repo.accounts(a.tenantId(),e.id(),c.year()).stream().anyMatch(x->x.companyId().equals(e.companyId())))throw WorkforceException.conflict();var p=policies.policy(a.tenantId(),contract.policyId(),contract.policyVersion()).orElseThrow();if(!p.status().equals("published")||c.openingOn().isAfter(p.effectiveTo()))throw WorkforceException.invalid();if(repo.hasUnreconciledFutureLeave(a.tenantId(),e.id(),e.companyId(),c.openingOn(),c.year()))throw new WorkforceException("LEAVE_OPENING_RECONCILIATION_REQUIRED",409);var seen=new HashSet<String>();for(var o:c.openings()){if(o==null||!Set.of("annual","sick","hospital","company").contains(o.kind())||!seen.add(o.kind())||o.remaining()==null||o.remaining().signum()<0||o.remaining().scale()>6)throw WorkforceException.invalid();var account=new Account(UUID.randomUUID(),e.id(),e.companyId(),c.year(),o.kind(),contract.partTime()?"hour":"day",contract.id(),c.openingOn(),engine.entitlement(a.tenantId(),p,contract,o.kind(),c.openingOn()),1);repo.create(a.tenantId(),a.actorId(),account);if(o.remaining().signum()>0)repo.credit(a.tenantId(),account,"opening","opening:"+id,engine.expiry(p,contract,c.year(),o.kind()),o.remaining());}if(seen.contains("sick")!=seen.contains("hospital"))throw WorkforceException.invalid();return finish(a,store,id,e.id(),c.year(),"enable",c);}
 @Transactional public Page refresh(CurrentActor a,UUID store,UUID id,Refresh c){if(c==null)throw WorkforceException.invalid();year(c.year());note(c.note());if(start(a,store,id,c.employeeId(),"refresh",c))return policies.replay(a,store,id,"refresh",c,Page.class).orElseThrow();var company=access.employee(a,store,c.employeeId(),true).companyId();for(var account:repo.accounts(a.tenantId(),c.employeeId(),c.year()).stream().filter(x->x.companyId().equals(company)).toList()){var issues=engine.issues(a.tenantId(),account);if(!issues.isEmpty())throw new WorkforceException(issues.getFirst(),409);engine.accrue(a,account);}return finish(a,store,id,c.employeeId(),c.year(),"refresh",c);}
 @Transactional public Page adjust(CurrentActor a,UUID store,UUID id,Adjust c){if(c==null||c.accountId()==null||c.expectedVersion()==null||c.quantity()==null||c.quantity().signum()==0||c.quantity().scale()>6||c.expiresOn()==null)throw WorkforceException.invalid();note(c.note());if(start(a,store,id,c.employeeId(),"adjust",c))return policies.replay(a,store,id,"adjust",c,Page.class).orElseThrow();access.notSelf(a,access.employee(a,store,c.employeeId(),true));var account=repo.find(a.tenantId(),c.accountId()).orElseThrow(WorkforceException::missing);if(!account.employeeId().equals(c.employeeId()))throw WorkforceException.missing();if(!account.companyId().equals(access.employee(a,store,c.employeeId(),true).companyId()))throw WorkforceException.forbidden();if(account.version()!=c.expectedVersion())throw WorkforceException.conflict();if(c.expiresOn().isBefore(engine.today()))throw WorkforceException.invalid();if(c.quantity().signum()>0)repo.credit(a.tenantId(),account,"adjust","adjust:"+id,c.expiresOn(),c.quantity());else{var remaining=c.quantity().negate();for(var lot:repo.lots(a.tenantId(),account.id())){if(lot.expiresOn().isBefore(engine.today()))continue;var take=lot.remaining().subtract(lot.reserved()).max(BigDecimal.ZERO).min(remaining);if(take.signum()>0){repo.entry(a.tenantId(),a.actorId(),account,lot.id(),id.toString(),"adjust",take.negate(),c.note());remaining=remaining.subtract(take);}if(remaining.signum()==0)break;}if(remaining.signum()>0)throw new WorkforceException("LEAVE_BALANCE_INSUFFICIENT",409);}return finish(a,store,id,c.employeeId(),account.year(),"adjust",c);}
 @Transactional public Page review(CurrentActor a,UUID store,UUID id,Review c){if(c==null||c.accountId()==null||c.contractId()==null||c.expectedVersion()==null||c.reviewOn()==null||c.available()==null||c.available().signum()<0||c.available().scale()>6)throw WorkforceException.invalid();note(c.note());if(start(a,store,id,c.employeeId(),"review",c))return policies.replay(a,store,id,"review",c,Page.class).orElseThrow();var e=access.employee(a,store,c.employeeId(),true);access.notSelf(a,e);var old=repo.find(a.tenantId(),c.accountId()).orElseThrow(WorkforceException::missing);if(!old.employeeId().equals(e.id())||!old.companyId().equals(e.companyId())||old.version()!=c.expectedVersion()||c.reviewOn().getYear()!=old.year()||c.reviewOn().isAfter(engine.today())||c.reviewOn().isBefore(old.openingOn()))throw WorkforceException.conflict();var contract=policies.contracts(a.tenantId(),e.id()).stream().filter(x->x.id().equals(c.contractId())&&x.companyId().equals(e.companyId())).findFirst().orElseThrow(WorkforceException::missing);if(!(contract.partTime()?"hour":"day").equals(old.unit()))throw new WorkforceException("LEAVE_UNIT_TRANSITION_REVIEW_REQUIRED",409);var p=policies.policy(a.tenantId(),contract.policyId(),contract.policyVersion()).orElseThrow();if(!p.status().equals("published")||c.reviewOn().isBefore(contract.effectiveFrom())||c.reviewOn().isAfter(p.effectiveTo()))throw WorkforceException.invalid();if(engine.issues(a.tenantId(),old).isEmpty()){engine.accrue(a,old);old=repo.find(a.tenantId(),old.id()).orElseThrow();}var available=engine.balance(a.tenantId(),old).available();var offset=engine.entitlement(a.tenantId(),p,contract,old.kind(),c.reviewOn()).subtract(repo.credited(a.tenantId(),old.id(),"accrual"));repo.review(a.tenantId(),old,contract.id(),c.reviewOn(),offset);var account=repo.find(a.tenantId(),old.id()).orElseThrow();var delta=c.available().subtract(available);if(delta.signum()>0)repo.credit(a.tenantId(),account,"review","review:"+id,engine.expiry(p,contract,account.year(),account.kind()),delta);else if(delta.signum()<0){var remaining=delta.negate();for(var lot:repo.lots(a.tenantId(),account.id())){if(lot.expiresOn().isBefore(engine.today()))continue;var take=lot.remaining().subtract(lot.reserved()).max(BigDecimal.ZERO).min(remaining);if(take.signum()>0){repo.entry(a.tenantId(),a.actorId(),account,lot.id(),id.toString(),"review",take.negate(),c.note());remaining=remaining.subtract(take);}if(remaining.signum()==0)break;}if(remaining.signum()>0)throw new WorkforceException("LEAVE_BALANCE_INSUFFICIENT",409);}return finish(a,store,id,e.id(),account.year(),"review",c);}
 public List<Binding> bindings(CurrentActor a,UUID store){gate.enter(a,store);return repo.bindings(a.tenantId(),store);}
 @Transactional public Binding bind(CurrentActor a,UUID store,UUID type,BindWrite c){gate.sourceWrite(a);gate.enter(a,store);gate.manage(a,store);if(c==null||c.expectedVersion()==null||c.expectedVersion()<0||c.kind()==null||!Set.of("annual","sick","hospital","company","unpaid").contains(c.kind()))throw WorkforceException.invalid();var t=types.find(a.tenantId(),store,type).orElseThrow(WorkforceException::missing);if(t.paid()==c.kind().equals("unpaid"))throw WorkforceException.invalid();policies.lock(a.tenantId(),"binding:"+type);var old=repo.bindings(a.tenantId(),store).stream().filter(x->x.typeId().equals(type)).findFirst().orElse(null);var next=new Binding(type,c.kind(),c.expectedVersion()+1);if(old!=null&&old.equals(next))return old;if((old==null?0:old.version())!=c.expectedVersion())throw WorkforceException.conflict();repo.binding(a.tenantId(),store,next);audit.changed(a,store,"leave-type-policy.bind",type,old,next);return next;}
}
